    # Extract next_page_token and follow if present
    try:
        body1 = resp1.json()
    except Exception:
        pytest.skip("First page response is not JSON; cannot test pagination")

    next_token = body1.get("next_page_token")
    if not next_token:
        pytest.skip("No next_page_token in first page; pagination not applicable")

    # Follow link using next_page_token
    params_next = {"page-token": next_token}
